import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import App from "./App";
import Home from "./routes/Home";
import Sign from "./routes/Sign";
import Verify from "./routes/Verify";
import "./styles/index.css";

// Caddy serves this bundle under both /assent/* and /verify/*. React Router's
// BrowserRouter uses the full path, so we mount the same app and route by path.
const root = document.getElementById("root")!;

createRoot(root).render(
  <StrictMode>
    <BrowserRouter>
      <Routes>
        <Route element={<App />}>
          {/* etch.locker paths */}
          <Route path="/assent" element={<Home />} />
          <Route path="/assent/sign" element={<Sign />} />
          <Route path="/assent/sign/:documentId" element={<Sign />} />
          {/* assent.to paths */}
          <Route path="/" element={<Home />} />
          <Route path="/sign" element={<Sign />} />
          <Route path="/sign/:documentId" element={<Sign />} />
          {/* Shared */}
          <Route path="/verify" element={<Verify />} />
          <Route path="/verify/:recordOrDocId" element={<Verify />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Route>
      </Routes>
    </BrowserRouter>
  </StrictMode>,
);
